@@ -0,0 +1,30 @@
+import assert from 'node:assert/strict';
+import {readFileSync} from 'node:fs';
+const read = path => JSON.parse(readFileSync(path,'utf8'));
+const ledger=read('docs/p9.0.7-contemporary-evidence-ledger.json');
+const previous=read('docs/p9.0.6.3-final-semantic-matrix.json');
+const policy=read('docs/p9.0.4.3-promotion-policy.json');
+assert.equal(ledger.scope_count,85);
+assert.equal(ledger.rows.length,85);
+assert.equal(new Set(ledger.rows.map(row=>row.actual_id)).size,85);
+assert.deepEqual(ledger.rows.map(row=>row.actual_id).sort(),previous.rows.map(row=>row.actual_id).sort());
+assert.equal(ledger.rows.filter(row=>row.match_type_2023==='UNIQUE_NAME_2023').length,69);
+assert.equal(ledger.rows.filter(row=>row.match_type_2023==='HOMONYM_MULTIPLE_ENTRIES_2023').length,11);
+assert.equal(ledger.rows.filter(row=>row.match_type_2023==='CURATED_ALIAS_POTENTIAL_MATCH').length,4);
+assert.equal(ledger.rows.filter(row=>row.match_type_2023==='NO_EXACT_2023_NAME').length,1);
+const lunga=ledger.rows.find(row=>row.name_ro==='Lunga');
+assert.equal(lunga.actual_id,'osm-r19001619');
+assert.equal(lunga.identity_role_decision,'MICRODISTRICT_SUPPORTED_BY_2026_INSTITUTIONAL_EVIDENCE_BUT_POLYGON_BINDING_UNVERIFIED');
+const crem=ledger.rows.find(row=>row.name_ro==='Cremenciug');
+assert.equal(crem.actual_id,'osm-r1216706');
+assert.equal(crem.geometric_parent_osm_id,'1702218');
+assert.equal(crem.claimed_de_facto_parent_osm_id,'1702219');
+assert(ledger.rows.every(row=>row.normative_amendment_chain_2023_2026==='NOT_EXHAUSTIVELY_VERIFIED'&&row.contemporary_2026_full_polygon_control==='NOT_CERTIFIED'&&row.legal_md_parent_preserved&&row.semantic_acceptance==='BLOCKED_INCOMPLETE'&&row.p91_import_allowed===false));
+assert.equal(ledger.certified_2026_full_polygon_control,0);
+assert.equal(ledger.certified_complete_normative_chain,0);
+assert.equal(ledger.semantically_accepted,0);
+assert.equal(ledger.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(ledger.p91_import_allowed,false);
+assert.equal(policy.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(policy.p91_import_allowed,false);
+console.log('P907_FAIL_CLOSED_PASS: 85 cases, 69 unique, 11 ambiguities, 4 aliases, Lunga separate, Cremenciug split, 0 contemporary certifications, P9.1 DENIED');
